        c = new XBORNID();
    }

    function _run(address caller) internal {
        caller = address(this);
        try c.XBornID() {} catch { return; }
        address owner = address(c);
        uint256 bal;
        try c.balanceOf(address(this)) returns (uint256 __r) { bal = __r; } catch { return; }
        uint256 dist;
        try c.totalDistributed() returns (uint256 __r) { dist = __r; } catch { return; }
        assertTrue(bal == dist);
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}

    fallback() external payable {}
}
